import ghidra.app.script.GhidraScript;import ghidra.app.decompiler.*;import ghidra.program.model.address.*;import ghidra.program.model.listing.*;import ghidra.program.model.pcode.*;import java.io.*;import java.util.*;
public class AliasPersistence extends GhidraScript {
 static class V{TreeSet<Long>s=new TreeSet<>();boolean u;V(boolean b){u=b;}V(long x){s.add(x&0xffffffffL);}public String toString(){StringBuilder b=new StringBuilder(u?"partial:":"known:");for(long x:s)b.append(String.format("%08x,",x));return b.toString();}}
 V ev(Varnode v,int n,HashSet<Varnode> path){
  if(v==null)return new V(true);if(v.isConstant())return new V(v.getOffset());if(n==0||path.contains(v))return new V(true);path.add(v);
  PcodeOp p=v.getDef();if(p==null){if(v.isAddress()&&v.getAddress().getOffset()>=0x26000&&v.getAddress().getOffset()+v.getSize()<=0x37fb8&&v.getSize()<=4)try{long val=0;for(int k=0;k<v.getSize();k++)val|=((long)getByte(v.getAddress().add(k))&255)<<(8*k);return new V(val);}catch(Exception e){}return new V(true);}
  int op=p.getOpcode();V a=ev(p.getInput(0),n-1,new HashSet<Varnode>(path));
  if(op==PcodeOp.COPY||op==PcodeOp.CAST||op==PcodeOp.INT_ZEXT||op==PcodeOp.INDIRECT)return a;
  if(op==PcodeOp.MULTIEQUAL){V z=new V(false);for(int k=0;k<p.getNumInputs();k++){V t=ev(p.getInput(k),n-1,new HashSet<Varnode>(path));z.u|=t.u;z.s.addAll(t.s);if(z.s.size()>32)return new V(true);}return z;}
  if(op==PcodeOp.LOAD){V q=ev(p.getInput(1),n-1,new HashSet<Varnode>(path));V z=new V(q.u);for(long x:q.s){if(x>=0x26000&&x+v.getSize()<=0x37fb8&&v.getSize()<=4)try{long val=0;for(int k=0;k<v.getSize();k++)val|=((long)getByte(toAddr(x+k))&255)<<(8*k);z.s.add(val);}catch(Exception e){z.u=true;}else z.u=true;}return z;}
  if(p.getNumInputs()<2)return new V(true);V b=ev(p.getInput(1),n-1,new HashSet<Varnode>(path));V z=new V(a.u||b.u);V c=p.getNumInputs()>2?ev(p.getInput(2),n-1,new HashSet<Varnode>(path)):new V(0L);
  for(long x:a.s)for(long y:b.s){long k;switch(op){case PcodeOp.INT_ADD:case PcodeOp.PTRSUB:k=x+y;break;case PcodeOp.INT_SUB:k=x-y;break;case PcodeOp.INT_MULT:k=x*y;break;case PcodeOp.INT_OR:k=x|y;break;case PcodeOp.INT_AND:k=x&y;break;case PcodeOp.INT_LEFT:k=x<<(y&31);break;case PcodeOp.INT_RIGHT:k=x>>>(y&31);break;case PcodeOp.SUBPIECE:k=x>>>(y*8);break;case PcodeOp.PTRADD:for(long t:c.s)z.s.add((x+y*t)&0xffffffffL);z.u|=c.u;continue;default:return new V(true);}z.s.add(k&0xffffffffL);if(z.s.size()>32)return new V(true);}return z;
 }
 boolean hit(V v){for(long x:v.s)if((x>=0x20003c40L&&x<0x20003ca8L)||(x>=0x75000&&x<0x78000)||(x>=0x20003fbcL&&x<0x20003fc8L))return true;return false;}
 public void run()throws Exception{String[] a=getScriptArgs();if(!a[1].equals(currentProgram.getExecutableSHA256()))throw new IllegalStateException("identity");File out=new File(a[0]);out.mkdirs();DecompInterface dc=new DecompInterface();DecompileOptions opt=new DecompileOptions();opt.setRespectReadOnly(false);dc.setOptions(opt);dc.openProgram(currentProgram);int total=0,ok=0,ops=0,hits=0;
 try(PrintWriter st=new PrintWriter(new File(out,"status.tsv"));PrintWriter all=new PrintWriter(new File(out,"all-call-values.tsv"));PrintWriter h=new PrintWriter(new File(out,"alias-candidates.tsv"))){for(Function f:currentProgram.getFunctionManager().getFunctions(true)){monitor.checkCancelled();total++;DecompileResults d=dc.decompileFunction(f,20,monitor);st.println(f.getEntryPoint()+"\t"+d.decompileCompleted()+"\t"+d.getErrorMessage());st.flush();if(!d.decompileCompleted())continue;ok++;Iterator<PcodeOpAST> it=d.getHighFunction().getPcodeOps();while(it.hasNext()){PcodeOpAST p=it.next();int op=p.getOpcode();if(op!=PcodeOp.CALL&&op!=PcodeOp.CALLIND&&op!=PcodeOp.BRANCHIND&&op!=PcodeOp.STORE&&op!=PcodeOp.LOAD)continue;ops++;boolean found=false;StringBuilder s=new StringBuilder(f.getEntryPoint()+"\t"+p.getSeqnum().getTarget()+"\t"+p.getMnemonic());if(op==PcodeOp.CALL)s.append("\ttarget="+p.getInput(0).getAddress());int k=(op==PcodeOp.CALL?1:(op==PcodeOp.STORE||op==PcodeOp.LOAD?1:0));for(;k<p.getNumInputs();k++){V v=ev(p.getInput(k),20,new HashSet<Varnode>());s.append("\ti"+k+"="+v);found|=hit(v);}if(op==PcodeOp.CALL||op==PcodeOp.CALLIND||op==PcodeOp.BRANCHIND)all.println(s);if(found){h.println(s);hits++;}}}}
 dc.dispose();try(PrintWriter w=new PrintWriter(new File(out,"coverage.txt"))){w.println("SHA256 "+currentProgram.getExecutableSHA256());w.println("functions "+total+" completed "+ok+" selected_pcode_ops "+ops+" candidate_ops "+hits);w.println("Locator only: depth20/set32, unknown inputs retained as partial; no path feasibility, interprocedural arguments, arbitrary RAM alias, whole-binary completeness claim. INDIRECT forwards source as candidate only. Original ROM data reads can be folded. Function boundaries inherited, may merge entries.");}}
}
